#include "../coh_wr_sampler.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
/* Compiled unchanged source setup/sampling blocks, generated by qualifier. */
void oracle_sampler(uint32_t,unsigned,int out[4]);
static unsigned checks;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"sampler line%d\n",__LINE__);exit(1);}}while(0)
int main(void){
    static const unsigned bits[]={6,7,9,10,13,14,16,26};
    for(unsigned mask=0;mask<256;mask++)for(unsigned m=0;m<5;m++){
        unsigned f=0;for(unsigned b=0;b<8;b++)if(mask&(1u<<b))f|=1u<<bits[b];
        CohWrSamplerSource s={f,0xde1,8,4,m,m?m:1,1,1.f};
        CohRenderTexture t,sentinel;memset(&t,0x5a,sizeof(t));sentinel=t;
        CohStatus status=coh_wr_sampler_project(&s,&t);
        int partial=m>0&&m<4&&!(f&(1u<<16))&&!(f&(1u<<26));
        CHECK(status==(partial?COH_UNSUPPORTED:COH_OK));
        if(partial){CHECK(!memcmp(&t,&sentinel,sizeof(t)));continue;}
        int want[4];oracle_sampler(f,m,want);
        CHECK(t.handle==0);CHECK((int)t.wrap_s==want[0]);CHECK((int)t.wrap_t==want[1]);
        CHECK((int)t.min_filter==want[2]);CHECK((int)t.mag_filter==want[3]);
    }
    CohWrSamplerSource s={0,0xde1,8,4,4,4,1,1};CohRenderTexture t,old;memset(&t,0x55,sizeof(t));old=t;
    CHECK(coh_wr_sampler_project(NULL,&t)==COH_INVALID);CHECK(coh_wr_sampler_project(&s,NULL)==COH_INVALID);
#define BAD(field,value,status) do{CohWrSamplerSource q=s;q.field=value;CHECK(coh_wr_sampler_project(&q,&t)==status);CHECK(!memcmp(&t,&old,sizeof(t)));}while(0)
    BAD(target,0x8513,COH_UNSUPPORTED);BAD(effective_flags,1u<<15,COH_UNSUPPORTED);BAD(effective_flags,1u<<17,COH_UNSUPPORTED);BAD(effective_flags,1u<<23,COH_UNSUPPORTED);BAD(effective_flags,1u<<30,COH_UNSUPPORTED);
    BAD(clamp_to_edge,0,COH_UNSUPPORTED);BAD(anisotropy,2,COH_UNSUPPORTED);BAD(width,0,COH_INVALID);BAD(mip_count,33,COH_INVALID);BAD(available_levels,3,COH_INVALID);BAD(mip_count,5,COH_INVALID);
    printf("{\"passed\":true,\"checks\":%u,\"source_cases\":1280,\"material_authority\":false}\n",checks);
}
